from collections import namedtuple
import io
from time import sleep, time
import wave
import numpy as np
import psutil
import pyaudio
from base64 import b64encode, b64decode

# Sounds
beep_low = ''''''
beep_high = ''''''


def battery_stats():
    try:
        return(psutil.sensors_battery())  #Returns battery stats (percent, secsleft, power_plugged).
    except Exception as e:
        battery_info = namedtuple('sbattery', ['percent', 'secsleft', 'power_plugged'])
        return(battery_info(percent=None, secsleft=None, power_plugged=None))

def encode_wav(wav_path):
    try:
        with open(wav_path, 'rb') as wav_file:
            return(b64encode(wav_file.read()).decode('utf-8'))
    except:
        return None
    
def decode_wav(encoded_string, file_name):
    wav_data = b64decode(encoded_string)
    try:
        with open(file_name, 'wb') as wav_file:
            wav_file.write(wav_data)
        return file_name
    except:
        return None
    
def play_sound(encoded_wav_string: str, duration=0.5, volume=1.0):
        # Decode the base64 string into binary data
    wav_data = b64decode(encoded_wav_string)
    
    # Use BytesIO to hold the binary data in memory
    wav_buffer = io.BytesIO(wav_data)
    
    def adjust_volume(data: bytes, sample_width: int, volume=1.0) -> bytes:
        """Adjust the volume of raw audio data."""
        volume = max(0.0, min(volume, 1.0))  # Clamp volume to range [0.0, 1.0]
        
        if sample_width == 1:  # 8-bit audio
            samples = np.frombuffer(data, dtype=np.uint8)
            samples = (samples - 128) * volume + 128  # Scale and re-normalize
            samples = np.clip(samples, 0, 255).astype(np.uint8)
        elif sample_width == 2:  # 16-bit audio
            samples = np.frombuffer(data, dtype=np.int16)
            samples = (samples * volume).astype(np.int16)
            samples = np.clip(samples, -32768, 32767)
        else:
            raise ValueError("Unsupported sample width")
        return samples.tobytes()

    # Open the BytesIO buffer as a wave file
    with wave.open(wav_buffer, 'rb') as wf:
        audio = pyaudio.PyAudio()
        
        # Configure the audio stream
        stream = audio.open(format=audio.get_format_from_width(wf.getsampwidth()),
                            channels=wf.getnchannels(),
                            rate=wf.getframerate(),
                            output=True)
        
         # Play sound for the specified duration
        chunk = 1024
        start_time = time()
        while time() - start_time < duration:
            data = wf.readframes(chunk)
            if not data:  # Restart the sound if it ends
                wf.rewind()
                data = wf.readframes(chunk)
            stream.write(data)

            # Apply volume adjustment
            adjusted_data = adjust_volume(data, wf.getsampwidth(), volume)
            stream.write(adjusted_data)
        
        # Close the stream
        stream.stop_stream()
        stream.close()
        audio.terminate()

def main():
    while True:
        try:
            battery_percent = battery_stats().percent
            charging = battery_stats().power_plugged
            
            if battery_percent is None:
                print("Could not retrieve battery stats.")
            
            if battery_percent > 90 and charging:
                play_sound(beep_high, duration=0.1, volume=0.2)
                sleep(1.5)
            
            elif battery_percent > 20 and battery_percent <= 30 and not charging:
                play_sound(beep_low, duration=0.1, volume=0.2)
                sleep(1.5)

            elif battery_percent <= 20 and not charging:
                play_sound(beep_low, duration=0.1, volume=0.2)
                sleep(1)

        except:
            pass

if __name__ == "__main__":

    main()

